def get_site_amplification(self, C, sites):
        """
        Returns the site amplification term
        """
        # Check if the site is in the molecule
        if sites in self.molecule.sites:
            return C * self.molecule.sites[sites].amplification
        else:
            raise Exception('Site ' + str(sites) + ' not in molecule')

